const RTT = 25;            // regional round-trip, ms
const dnsCold = 50;        // resolver walk, ms

// COLD first visit: DNS walk + TCP 1 RTT + TLS new 1 RTT + HTTP 1 RTT
const cold = dnsCold + RTT + RTT + RTT;

// WARM repeat visit: DNS cached (~0), TCP pooled (0), TLS 0-RTT (0), HTTP 1 RTT
const dnsWarm = 0;         // OS resolver cache
const tcpWarm = 0;         // connection pooled / keep-alive
const tlsWarm = 0;         // 0-RTT resumption via PSK
const warm = dnsWarm + tcpWarm + tlsWarm + RTT;

console.log('cold TTFB =', cold, 'ms');
console.log('warm TTFB =', warm, 'ms');
console.log('eliminated =', cold - warm, 'ms');
